#include <stddef.h>
int adc_raw_to_millivolts(unsigned int raw, int bits, unsigned int vref_mv, unsigned int *out_mv)
{
    if (out_mv == NULL) {
        return -1;
    }
    if (vref_mv == 0u) {
        return -1;
    }
    if (bits < 10 || bits > 16) {
        return -1;                      /* 素材：ADC 精度通常为 10~16 位 */
    }

    unsigned int full_scale = 1u << bits;   /* 12 位 -> 4096 级 */
    if (raw >= full_scale) {
        return -1;                      /* 超出该分辨率的满量程读数 */
    }

    /* 用 64 位中间量，避免 raw * vref_mv 在高分辨率/高参考电压下溢出 32 位 */
    unsigned long long mv =
        (unsigned long long)raw * (unsigned long long)vref_mv;
    *out_mv = (unsigned int)(mv / (unsigned long long)full_scale);
    return 0;
}
